 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Colors forming any multi-cell 4-connected component belong to the scene;
    # isolated-color speckles are corruption to be restored from their neighbors.
    seen = [[False] * w for _ in range(h)]
    multi_colors = set()
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen[r][c] = True
            size = 0
            for rr, cc in q:
                size += 1
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == color:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            if size > 1:
                multi_colors.add(color)

    out = [row[:] for row in grid]
    speckles = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in multi_colors]
    # Use the surrounding established regions, not other speckles, to infer each cell.
    for r, c in speckles:
        counts = Counter(grid[nr][nc] for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                         if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] in multi_colors)
        if not counts:
            counts = Counter(grid[nr][nc] for nr in range(max(0,r-1),min(h,r+2))
                             for nc in range(max(0,c-1),min(w,c+2))
                             if (nr,nc)!=(r,c) and grid[nr][nc] in multi_colors)
        if counts:
            out[r][c] = counts.most_common(1)[0][0]
    return out
"
}

