                        seen[nr][nc] = True
                        stack.append((nr, nc))
            if size > 1:
                core_colors.add(color)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(widths[r]):
            if grid[r][c] in core_colors:
                continue

            # Adjacent coherent regions are the strongest cue.
            cardinal = Counter(
                grid[nr][nc]
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                if 0 <= nr < h and 0 <= nc < widths[nr]
                and grid[nr][nc] in core_colors
            )
            if cardinal and max(cardinal.values()) > sum(cardinal.values()) / 2:
                out[r][c] = cardinal.most_common(1)[0][0]
                continue

            # Fill a missing cell in a 2x2 block when the other three agree.
            patch_counts = Counter()
            for r0 in (r-1, r):
