                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == color:
                        seen[nr][nc] = True
                        stack.append((nr, nc))
            if len(cells) > 1:
                colors.add(color)
                for rr, cc in cells:
                    core[rr][cc] = True

    for r in range(h):
        for c in range(w):
            if core[r][c]:
                continue
            direct = Counter(grid[nr][nc] for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                             if 0 <= nr < h and 0 <= nc < w and core[nr][nc])
            if grid[r][c] == 7 and direct.get(2, 0):
