def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    core = [[False] * w for _ in range(h)]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = set()

    # Mark pixels in any multi-cell connected region as reliable structure.
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            stack, cells = [(r, c)], []
            seen[r][c] = True
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == color:
                        seen[nr][nc] = True
                        stack.append((nr, nc))
            if len(cells) > 1:
                colors.add(color)
                for rr, cc in cells:
                    core[rr][cc] = True

    for r in range(h):
        for c in range(w):
            if core[r][c]:
                continue
            color = grid[r][c]
            # A stray pixel of the dominant background usually is already correct.
            # Still fill a one-cell hole when it completes a uniform 2x2 patch.
            patch = Counter()
            for r0 in (r-1, r):
                for c0 in (c-1, c):
                    coords = [(rr,cc) for rr in (r0,r0+1) for cc in (c0,c0+1)]
                    if all(0 <= rr < h and 0 <= cc < w for rr,cc in coords):
                        for target in colors:
                            if sum(grid[rr][cc] == target or (rr,cc)==(r,c) for rr,cc in coords) == 4:
                                patch[target] += 1
            if patch:
                out[r][c] = patch.most_common(1)[0][0]
                continue
            if color == background:
                continue

            # Assignment by local majority of reliable structure; tied neighborhoods
            # resolve to the dominant background rather than bridging adjacent objects.
            local = Counter(grid[rr][cc] for rr in range(max(0,r-1),min(h,r+2))
                            for cc in range(max(0,c-1),min(w,c+2))
                            if (rr,cc)!=(r,c) and core[rr][cc])
            if local:
                top = max(local.values())
                winners = [v for v,n in local.items() if n == top]
                if len(winners) == 1:
                    out[r][c] = winners[0]
                    continue
                if background in winners:
                    out[r][c] = background
                    continue

            # For a one-pixel island without an informative 3x3 neighborhood,
            # choose the nearest coherent component, favoring background on ties.
            for dist in range(1, h+w):
                nearby = Counter(grid[rr][cc] for rr in range(max(0,r-dist),min(h,r+dist+1))
                                 for cc in range(max(0,c-dist),min(w,c+dist+1))
                                 if abs(rr-r)+abs(cc-c)==dist and core[rr][cc])
                if nearby:
                    top = max(nearby.values())
                    winners = [v for v,n in nearby.items() if n == top]
                    out[r][c] = background if background in winners else winners[0]
                    break
    return out
