def transform(grid):
    h = len(grid)
    out = [row[:] for row in grid]
    seen = [[False] * len(row) for row in grid]
    core = [[False] * len(row) for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Large connected patches are the intended solid objects. Tiny components
    # (one or two pixels) are stray marks unless they complete a 2x2 patch.
    components = []
    for r, row in enumerate(grid):
        for c in range(len(row)):
            if seen[r][c]:
                continue
            color = grid[r][c]
            stack, cells = [(r, c)], []
            seen[r][c] = True
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if (0 <= nr < h and 0 <= nc < len(grid[nr]) and
                            not seen[nr][nc] and grid[nr][nc] == color):
                        seen[nr][nc] = True
                        stack.append((nr, nc))
            components.append((color, cells))
            if len(cells) >= 3:
                for rr, cc in cells:
                    core[rr][cc] = True

    # Repair any cell that interrupts a uniform 2x2 patch. This also fixes
    # corrupted cells that touch a large object and so are not isolated.
    for r, row in enumerate(grid):
        for c in range(len(row)):
            patch = Counter()
            for r0 in (r-1, r):
                for c0 in (c-1, c):
                    coords = [(rr,cc) for rr in (r0,r0+1) for cc in (c0,c0+1)]
                    if all(0 <= rr < h and 0 <= cc < len(grid[rr]) for rr,cc in coords):
                        for color in range(10):
                            if color != grid[r][c] and sum(
                                grid[rr][cc] == color for rr,cc in coords if (rr,cc) != (r,c)
                            ) == 3:
                                patch[color] += 1
            if patch:
                out[r][c] = patch.most_common(1)[0][0]

    # Remove tiny components that are not repaired by the local solid-patch rule.
    for color, cells in components:
        if len(cells) <= 2:
            for r, c in cells:
                if out[r][c] == grid[r][c]:
                    out[r][c] = background
    return out
