def transform(grid):
    h = len(grid)
    w = max(map(len, grid))
    out = [row[:] for row in grid]
    seen = [[False] * len(row) for row in grid]
    core = [[False] * len(row) for row in grid]
    flat = [v for row in grid for v in row]
    background = 3 if 3 in flat else Counter(flat).most_common(1)[0][0]

    components = []
    for r, row in enumerate(grid):
        for c in range(len(row)):
            if seen[r][c]:
                continue
            color = grid[r][c]
            stack, cells = [(r, c)], []
            seen[r][c] = True
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if (0 <= nr < h and 0 <= nc < len(grid[nr]) and
                            not seen[nr][nc] and grid[nr][nc] == color):
                        seen[nr][nc] = True
                        stack.append((nr, nc))
            components.append((color, cells))
            if len(cells) >= 3:
                for rr, cc in cells:
                    core[rr][cc] = True

    for r, row in enumerate(grid):
        for c in range(len(row)):
            # Restore an anomalous pixel within the core if its 8-neighbors
            # overwhelmingly belong to another solid object/background.
            if core[r][c]:
                near = Counter(grid[rr][cc] for rr in range(max(0,r-1),min(h,r+2))
                               for cc in range(max(0,c-1),min(len(grid[rr]),c+2))
                               if (rr,cc)!=(r,c))
                if near:
                    col, count = near.most_common(1)[0]
                    if count >= 5 and col != grid[r][c]:
                        out[r][c] = col
                        core[r][c] = False
                continue

            # Correct one-cell damage in uniform 2x2 patches.
            patch = Counter()
            for r0 in (r-1,r):
                for c0 in (c-1,c):
                    coords = [(rr,cc) for rr in (r0,r0+1) for cc in (c0,c0+1)]
                    if all(0 <= rr < h and 0 <= cc < len(grid[rr]) for rr,cc in coords):
                        for color in range(10):
                            if color != grid[r][c] and sum(
                                grid[rr][cc] == color for rr,cc in coords if (rr,cc)!=(r,c)
                            ) == 3:
                                patch[color] += 1
            if patch:
                out[r][c] = patch.most_common(1)[0][0]
                continue

            color = grid[r][c]
            if color == background:
                continue
            local = Counter(grid[rr][cc] for rr in range(max(0,r-1),min(h,r+2))
                            for cc in range(max(0,c-1),min(len(grid[rr]),c+2))
                            if (rr,cc)!=(r,c) and core[rr][cc])
            if local:
                top = max(local.values())
                winners = [v for v,n in local.items() if n == top]
                if len(winners) == 1:
                    out[r][c] = winners[0]
                else:
                    out[r][c] = background
            else:
                out[r][c] = background

    return out
