def transform(grid):
    h = len(grid)
    out = [row[:] for row in grid]
    seen = [[False] * len(row) for row in grid]
    component_size = [[0] * len(row) for row in grid]

    # Identify coherent regions; small disconnected fragments are likely noise.
    for r, row in enumerate(grid):
        for c in range(len(row)):
            if seen[r][c]:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if (0 <= nr < h and 0 <= nc < len(grid[nr]) and
                            not seen[nr][nc] and grid[nr][nc] == color):
                        seen[nr][nc] = True
                        stack.append((nr, nc))
            for rr, cc in cells:
                component_size[rr][cc] = len(cells)

    flat = [v for row in grid for v in row]
    background = 3 if 3 in flat else Counter(flat).most_common(1)[0][0]
    for r, row in enumerate(grid):
        for c in range(len(row)):
            color = grid[r][c]
            # In this instance 0, 4, and 6 are corrupting marks; other colors
            # belong to the repeated solid shapes. Also repair any tiny island.
            if color not in (0, 4, 6) and component_size[r][c] >= 3:
                continue
            # A hole in a solid 2x2 patch has an unambiguous restoration color.
            patch = Counter()
            for r0 in (r-1, r):
                for c0 in (c-1, c):
                    cells = [(rr,cc) for rr in (r0,r0+1) for cc in (c0,c0+1)]
                    if all(0 <= rr < h and 0 <= cc < len(grid[rr]) for rr,cc in cells):
                        vals = [grid[rr][cc] for rr,cc in cells if (rr,cc) != (r,c)]
                        if len(vals) == 3 and vals[0] == vals[1] == vals[2]:
